    return (StringBuffer('StaffPhotosCompanion(')
          ..write('staffId: $staffId, ')
          ..write('image: $image, ')
          ..write('updatedAt: $updatedAt, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

